CustomStylesJson:
.report-footer img {
    content: url("https://sporttech-io-s3.eu-central-1.linodeobjects.com/2024-TRA-WCUP-COTBUS/footer.svg");
    width:190mm;
}
@media screen {
    .webver .report-footer  {
        display: block !important;

    }
    .report-footer .info-block {
        display: none;
    }
}
.logo img {
    content: url("https://sporttech-io-s3.eu-central-1.linodeobjects.com/2024-TRA-WCUP-COTBUS/Logo-WC-TRA-CMYK.png")
}

// Soreboards
.scoreboard-block.wide {
	 background: green;
	 padding-top: 2px;
}
 .scoreboard-block.wide .title-block {
	 background: white;
	 border-radius: 10px;
}
 .scoreboard-block.wide .title-block .competition-title, .scoreboard-block.wide .title-block .stage-kind {
	 color: black;
}
 .scoreboard-block.wide .frame-stage-standings {
	 margin-top: 5px;
	 padding-left: 15px;
	 background: #000d80;
	 border-radius: 10px;
	 overflow: hidden;
	 height: 475px;
}
 .scoreboard-block.wide .screen.frame .athletes h1 {
	 background: #000d80;
	 margin-bottom: 0px;
	 padding: 10px;
	 border-radius: 10px 10px 0px 0px;
	 margin-top: 5px;
}
 .scoreboard-block.wide .screen.frame .frame-block.frame-results {
	 padding: 10px;
	 background: #000d80;
	 border-radius: 0px 0px 10px 10px;
}
 .scoreboard-block.wide .screen.frame .frame-block.frame-results .line2 {
	 margin-top: 0px;
}
 .scoreboard-block.wide .screen.frame .frame-block.frame-intro {
	 padding: 10px;
	 margin-top: 5px;
	 background: #000d80;
	 border-radius: 10px;
}
 .scoreboard-block.wide .screen.frame .frame-block.frame-intro .photos {
	 height: 370px;
}
 .scoreboard-block.wide .screen.frame .frame-block.frame-intro {
	 border-radius: 10px 10px 0px 0px;
}
.scoreboard-block.wide .frame-results {
	 height: 350px;
}
//// SYN
.scoreboard-block.wide.SYN .screen.frame .frame-block.frame-intro .photos {
	 height: 300px;
}

 .scoreboard-block.wide.SYN .screen.frame .frame-block.frame-intro .athletes {
	 display: flex;
	 overflow: hidden;
}
 .scoreboard-block.wide.SYN .screen.frame .frame-block.frame-intro .athletes li:first-child .athlete-givenname:after {
	 content: ",";
}
 .scoreboard-block.wide.SYN .screen.frame .frame-block.frame-intro .athletes li:nth-child(2) .country-small, .scoreboard-block.wide.SYN .screen.frame .frame-block.frame-intro .athletes li:nth-child(2) .athlete-repr {
	 display: none;
}

.stage.stage-page .main .groups .group .DNS {
    text-decoration: none;
    filter: opacity(1)
}
.judgeN {
    display: none;
}

.results.results-page.judges .panel.grid:before {
    content: "Judges panel";
    font-size:20px;
}
